// Figures out if the link is a YouTube video, a YouTube playlist or a SoundCloud track.
// Video:    youtube.com/watch?v=...  youtu.be/...  youtube.com/shorts/...
// Playlist: youtube.com/playlist?list=...
// SoundCloud: soundcloud.com/artist/track  (one track only, not sets/playlists)
return $input.all().map(item => {
  const text = String(item.json.text || '').trim();
  let type = 'invalid';
  let youtubeId = null;
  let soundcloudUrl = null;

  const playlist = text.match(/youtube\.com\/playlist\?(?:.*&)?list=([\w-]+)/);
  // SoundCloud: the 2nd part of the path must be a track name, not "sets", "likes"...
  const sc = text.match(/(?:https?:\/\/)?(?:m\.)?soundcloud\.com\/([\w-]+)\/([\w-]+)/);
  const notATrack = ['sets', 'likes', 'tracks', 'albums', 'reposts', 'following', 'followers', 'popular-tracks'];
  const video = text.match(/(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/)|youtu\.be\/)([\w-]{11})/);

  if (playlist) {
    type = 'playlist';
    youtubeId = playlist[1];
  } else if (video) {
    type = 'video';
    youtubeId = video[1];
  } else if (sc && !notATrack.includes(sc[2].toLowerCase())) {
    type = 'soundcloud';
    soundcloudUrl = `https://soundcloud.com/${sc[1]}/${sc[2]}`;
  }

  return { json: { ...item.json, type, youtubeId, soundcloudUrl, isValid: type !== 'invalid' } };
});

// Two sources, two formats, one output: one { rawTitle } item per video.
//  - video branch:    oEmbed returns { title: "..." }
//  - playlist branch: the API returns { items: [ { snippet: { title } } ] }, one page of 50 per item
const titles = [];
for (const res of $input.all()) {
  const j = res.json;

  if (typeof j.title === 'string') {                       // video (oEmbed)
    titles.push({ json: { rawTitle: j.title } });

  } else if (Array.isArray(j.items)) {                     // playlist (API)
    for (const v of j.items) {
      const title = v.snippet?.title;
      // a playlist can contain deleted or private videos: skip them
      if (!title || title === 'Deleted video' || title === 'Private video') continue;
      titles.push({ json: { rawTitle: title } });
    }
  }
  // otherwise the video or playlist wasn't reachable (the HTTP node returned an error)
}
// Nothing came back: keep going anyway so the user still gets an answer.
return titles.length ? titles : [{ json: { rawTitle: '' } }];

// Compares the tracks I found with what's already in the playlist,
// then builds the summary message.

// "Read playlist" brings the playlist page by page (50 tracks per page).
// Since February 2026 Spotify calls the track "item"; "track" is the old name.
const pages = $input.all().map(i => i.json);
const readFailed = pages.length === 0 || pages.some(p => p.error);   // couldn't read it: better to add nothing
const existing = new Set(
  pages
    .flatMap(p => p.items || [])
    .map(x => x.item?.uri ?? x.track?.uri)
    .filter(Boolean)
);

const results = $('Resolve tracks').all().map(i => i.json);
const cfg = $('Config & message').first().json;

if (readFailed) {
  return [{ json: { toAdd: [], toReview: [], chatId: cfg.chatId,
    reply: "⚠️ I couldn't read your playlist, so I added nothing. It may have been deleted or changed. Send /playlist to choose it again." } }];
}

const toAdd = [], added = [], already = [], notFound = [];
const toReview = [];
const reviewSeen = new Set();   // same title twice in one batch
const seen = new Set();         // same track twice in one batch

for (const r of results) {
  if (r.status !== 'found') {
    const t = r.rawTitle || '(video not found or private)';
    notFound.push(r.status === 'error' ? `${t} (Spotify error, retry later)` : t);
    // Review queue: only titles shaped like "Artist - Title" (a mix has nothing to suggest).
    if (r.status === 'not found' && r.hasSeparator && r.rawTitle && r.candidates?.length && !reviewSeen.has(r.rawTitle)) {
      reviewSeen.add(r.rawTitle);
      toReview.push({
        ref: Math.random().toString(36).slice(2, 10),
        title: r.rawTitle,
        candidates: JSON.stringify(r.candidates),
        status: 'pending',
        chatId: String(cfg.chatId),
      });
    }
    continue;
  }
  const label = `${r.artist} — ${r.name}`;
  if (existing.has(r.uri) || seen.has(r.uri)) {
    already.push(label);
    continue;
  }
  seen.add(r.uri);
  toAdd.push(r.uri);
  added.push(label);
}

// Telegram reads this message as Markdown: a _ or * in a title would make the send fail.
const esc = s => String(s).replace(/([_*`\[])/g, '\\$1');
// Telegram limits a message to 4096 characters, so long lists get cut.
const list = (items, max = 15) => {
  if (!items.length) return '';
  const shown = items.slice(0, max).map(s => '• ' + esc(s));
  if (items.length > max) shown.push(`… and ${items.length - max} more`);
  return '\n' + shown.join('\n');
};
const rescued = results.filter(r => r.rescuedByAI).length;
const aiFailed = results.filter(r => r.aiTried && !r.rescuedByAI).length;
const aiNote = (rescued || aiFailed)
  ? '\n\n🤖 AI: ' + [
      rescued ? `${rescued} title(s) rescued` : '',
      aiFailed ? `${aiFailed} tried, no match` : '',
    ].filter(Boolean).join(', ')
  : '';

const reply = [
  `✅ Added: ${added.length}${list(added)}`,
  `↩️ Already in the playlist: ${already.length}${list(already)}`,
  `❓ Not found: ${notFound.length}${list(notFound)}`,
].join('\n\n') + (toReview.length
  ? `\n\n🔎 ${toReview.length} refused title(s) with suggestions. Send /review to pick.`
  : '') + aiNote;

return [{ json: { toAdd, reply, chatId: cfg.chatId, toReview } }];

// A button click arrives as a "callback_query" event.
// Button format: "ok|<ref>|<candidate number>" or "no|<ref>".
const cb = $('Telegram Trigger').first().json.callback_query;
const [tag, ref, idx] = String(cb.data || '').split('|');
return [{ json: {
  queryId: cb.id,
  chatId: String(cb.message?.chat?.id ?? cb.from?.id ?? ''),
  action: tag === 'ok' ? 'pick' : tag === 'no' ? 'skip' : 'other',
  ref: ref || '',
  idx: Number(idx) || 0,
} }];

// The row was just "locked" by the update (pending -> added or skipped),
// so two taps on the same button can't add the track twice.
const row = $input.first().json;
const click = $('Read the click').first().json;
let candidates = [];
try { candidates = JSON.parse(row.candidates || '[]'); } catch (e) {}
const chosen = click.action === 'pick' ? candidates[click.idx] : null;
return [{ json: {
  action: chosen ? 'pick' : 'skip',
  uri: chosen?.uri ?? '',
  chatId: click.chatId,
  notice: chosen ? `✅ Added: ${chosen.label}` : `⏭ Skipped: ${row.title}`,
} }];

// The context (chat + confirmation message) comes from one of these three nodes:
// only one of them ran in this execution.
const ctx = (() => {
  for (const name of ['Context after pick', 'Already handled', 'Command chat']) {
    try { return $(name).first().json; } catch (e) { /* that node didn't run */ }
  }
  return {};
})();

const row = $input.first().json;          // the next pending case, or empty
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const short = (s, n = 40) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const notice = ctx.notice ? esc(ctx.notice) + '\n\n' : '';

if (!row.ref) {
  return [{ json: { chatId: ctx.chatId, hasCase: false, text: notice + 'Nothing left to review.' } }];
}

let candidates = [];
try { candidates = JSON.parse(row.candidates || '[]').slice(0, 3); } catch (e) {}
const lines = candidates.map((c, i) => `${i + 1}. ${esc(c.label)}`).join('\n');
// Three candidate buttons (a dead "—" button if Spotify offered fewer) + "None of these".
const btn = i => candidates[i]
  ? { t: `${i + 1}. ${short(candidates[i].label)}`, d: `ok|${row.ref}|${i}` }
  : { t: '—', d: `xx|${row.ref}` };

return [{ json: {
  chatId: ctx.chatId,
  hasCase: true,
  text: `${notice}🔎 <b>${esc(row.title)}</b>\nSpotify suggests:\n${lines}`,
  b1t: btn(0).t, b1d: btn(0).d, b2t: btn(1).t, b2d: btn(1).d, b3t: btn(2).t, b3d: btn(2).d,
  skipData: `no|${row.ref}`,
} }];

// Reads the Telegram event (a normal message, a button click OR a screenshot) and keeps what I need.
const ev = $('Telegram Trigger').first().json;
const click = ev.callback_query;
const msg = ev.message || {};
const chatId = String(click?.message?.chat?.id ?? click?.from?.id ?? msg.chat?.id ?? '');

// A screenshot arrives as "photo" (several sizes: I take the biggest, the last one)
// or as a "document" when it is sent as a file without compression.
const photos = Array.isArray(msg.photo) ? msg.photo : [];
const doc = msg.document && String(msg.document.mime_type || '').startsWith('image/') ? msg.document : null;
const photoId = photos.length ? photos[photos.length - 1].file_id : (doc ? doc.file_id : '');

return [{ json: {
  chatId,
  isClick: !!click,
  text: click ? '' : String(msg.text ?? ''),
  hasPhoto: !click && !!photoId,
  photoId,
} }];

// The "brain" of the front door: where does this event go?
// It depends on 2 things: what the person sent, and how far they got in the setup.
//   step "none"         = I don't know this person yet
//   step "connecting"   = they got a Spotify link but didn't finish
//   step "need_playlist"= Spotify is connected, I still need the playlist link
//   step "ready"        = everything is set, they can send YouTube links
const who = $('Who is writing?').first().json;
const user = $input.first().json;              // the person's row in the "users" table, or {} if unknown
const step = user.step || 'none';

// "/review@MyBot blabla" -> "/review"
const text = who.text.trim();
const cmd = text.startsWith('/') ? text.split(/\s/)[0].split('@')[0].toLowerCase() : '';

let route, action = '';
if (cmd === '/disconnect') {
  route = 'disconnect';
} else if (cmd === '/connect') {
  route = 'connect';
} else if (step === 'none' || step === 'connecting') {
  route = 'connect';
} else if (step === 'need_playlist') {
  if (who.isClick || cmd) { route = 'ask_playlist'; }
  else { route = 'spotify'; action = 'playlist_link'; }
} else {                                        // step === 'ready'
  if (cmd === '/start' || cmd === '/help') route = 'help';
  else if (cmd === '/playlist') route = 'change_playlist';
  else if (cmd === '/review') route = 'review';
  else { route = 'spotify'; action = who.isClick ? 'click' : (who.hasPhoto ? 'photo' : 'link'); }
}

// playlist name made safe for a Telegram HTML message
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { route, action, chatId: who.chatId, playlistName: esc(user.playlistName) } }];

// Builds the personal Spotify login link for this person.
const app = $('App settings').first().json;
const who = $('Who is writing?').first().json;

if (!app.clientId || !app.redirectUri || /PASTE|YOUR-INSTANCE/.test(app.clientId + app.redirectUri)) {
  throw new Error('Open the "App settings" node and fill in the Spotify Client ID and the redirect URL.');
}

// "state" = a random one-time code. It comes back in the redirect, and that's how
// I know which Telegram chat the Spotify answer belongs to.
const rand = () => {
  try { return crypto.randomUUID().replace(/-/g, ''); }
  catch (e) { return Array.from({ length: 4 }, () => Math.random().toString(36).slice(2)).join(''); }
};
const state = rand();

const enc = encodeURIComponent;
const url = 'https://accounts.spotify.com/authorize?' + [
  'response_type=code',
  'client_id=' + enc(app.clientId),
  'scope=' + enc('playlist-read-private playlist-modify-public playlist-modify-private'),  // only what I need
  'redirect_uri=' + enc(app.redirectUri),
  'state=' + state,
  'show_dialog=true',
].join('&');

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const text = [
  '👋 Hi! Before I can fill your Spotify playlist I need your OK (one time only).',
  '',
  `1. Tap this link: <a href="${esc(url)}">Connect my Spotify</a>`,
  '2. Log in to Spotify and press "Agree"',
  '3. Come back here: I will ask you for your playlist link',
  '',
  'I never see your password, and you can stop any time with /disconnect.',
  'If Spotify shows an error, the owner of this bot has to add your Spotify email first.',
].join('\n');

return [{ json: { chatId: who.chatId, state, stateAt: String(Date.now()), text } }];

// Spotify just sent the person back to my webhook with ?code=...&state=...
// Is it really one of my users, with a link I created recently?
const q = $('Spotify redirect').first().json.query || {};
const row = $input.first().json;               // the row that owns this "state", or {} if none
const fresh = Number(row.stateAt) > 0 && (Date.now() - Number(row.stateAt)) < 30 * 60 * 1000;   // 30 minutes

const ok = !!(q.code && q.state && row.chatId && row.oauthState === q.state && row.step === 'connecting' && fresh);
return [{ json: { ok, code: q.code || '', chatId: ok ? String(row.chatId) : '' } }];

// Finds the playlist id in what the person sent. Two usual forms:
//   https://open.spotify.com/playlist/3QNjy2ijyRhpqybVATe1qP?si=...
//   spotify:playlist:3QNjy2ijyRhpqybVATe1qP
const text = String($('Who is writing?').first().json.text || '');
const m = text.match(/playlist[\/:]([A-Za-z0-9]{22})/);
return [{ json: { ok: !!m, playlistId: m ? m[1] : '' } }];

// Is this playlist usable? It has to belong to the person.
// (Spotify only lets my app change playlists of the user who logged in.)
const link = $('Read the playlist link').first().json;
const me = $('Spotify: who am I').first().json;
const pl = $input.first().json;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fail = message => [{ json: { ok: false, message } }];

if (me.error || !me.id) return fail("Spotify didn't answer. Try again in a minute.");
if (pl.error || !pl.id) return fail("I can't open that playlist. Check the link, and make sure it is a playlist you created yourself.");
if (pl.owner?.id && pl.owner.id !== me.id) {
  return fail('That playlist belongs to someone else. I can only fill a playlist you created: make your own one (or copy it) and send me its link.');
}

const name = pl.name || 'your playlist';
return [{ json: { ok: true, playlistId: link.playlistId, playlistName: name, nameHtml: esc(name) } }];

// Turns the Error Trigger data into a readable message.
const CHAT_ID = '8642255457';   // my chat id: the alert lands in my conversation with the bot

const d = $input.first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = s => esc(s).replace(/"/g, '&quot;');
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const wfName = d.workflow?.name ?? 'unknown workflow';
const isTrigger = !d.execution && !!d.trigger;      // the trigger itself failed (e.g. Telegram webhook)
const err = d.execution?.error ?? d.trigger?.error ?? {};
const message = typeof err === 'string' ? err : (err.message ?? 'no message');
const detail = err.description && err.description !== message ? err.description : '';
const node = isTrigger ? 'the trigger' : (d.execution?.lastNodeExecuted ?? 'unknown');
const url = d.execution?.url;
let when;
try { when = new Date().toLocaleString('en-GB', { timeZone: 'Europe/Paris' }); }
catch (e) { when = new Date().toISOString(); }

const lines = [
  '⚠️ <b>Error in a workflow</b>',
  `<b>Workflow:</b> ${esc(wfName)}`,
  `<b>Failed node:</b> ${esc(node)}`,
  `<b>Message:</b> ${esc(cut(String(message), 500))}`,
];
if (detail) lines.push(`<b>Details:</b> ${esc(cut(String(detail), 300))}`);
if (url) lines.push(`<b>Run:</b> <a href="${escAttr(url)}">open in n8n</a>`);
lines.push(`<i>${esc(when)}</i>`);

return [{ json: { chatId: CHAT_ID, text: lines.join('\n') } }];

// SoundCloud's oEmbed answers with a title like "Track by Artist" and an author_name.
// I rewrite it as "Artist - Track", the shape the rest of the workflow already understands.
return $input.all().map(item => {
  const j = item.json;
  if (typeof j.title !== 'string') return item;      // error or private track: "Extract titles" deals with it
  const author = String(j.author_name || '').trim();
  let track = j.title.trim();
  if (author && track.toLowerCase().endsWith(' by ' + author.toLowerCase())) {
    track = track.slice(0, -(author.length + 4)).trim();
  }
  // some uploads already say "Artist - Track" in the title: keep it as it is
  const title = (author && !/\s[-–—]\s/.test(track)) ? `${author} - ${track}` : track;
  return { json: { title } };
});

// The AI answers with a JSON list: [{ "artist": "...", "track": "..." }, ...].
// Each song becomes "Artist - Track", the same shape as a YouTube title,
// so everything after this node works unchanged.
let songs = [];
try {
  const text = String($input.first().json.text ?? $input.first().json.output ?? '');
  songs = JSON.parse(text.match(/\[[\s\S]*\]/)[0]);   // the JSON part, even with ```json around it
} catch (e) { /* no answer or not JSON: nothing readable */ }

const seen = new Set();
const titles = [];
for (const s of Array.isArray(songs) ? songs : []) {
  const artist = String(s?.artist ?? '').trim();
  const track = String(s?.track ?? '').trim();
  const rawTitle = artist ? `${artist} - ${track}` : track;
  if (!track || seen.has(rawTitle.toLowerCase())) continue;   // empty, or twice on the image
  seen.add(rawTitle.toLowerCase());
  titles.push({ json: { rawTitle } });
}
// Nothing readable: the summary will say so in "Not found".
return titles.length ? titles.slice(0, 100) : [{ json: { rawTitle: '' } }];
